package dev.workshopvideo;
import android.app.Activity;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.content.*;import org.json.*;
/** Same renderer and sensors as real wallpaper, without applying anything to the system. */
public final class WallpaperPreviewActivity extends Activity {
 private WallpaperRenderer renderer;private MotionInput input;private TextureView texture;private Surface surface;private JSONObject config;private String id;private boolean resumed;private TextView status,pageLabel;private LinearLayout pageControls;private float scroll=.5f;private int pages;private SeekBar page;private final dev.workshopvideo.core.LauncherPaging paging=new dev.workshopvideo.core.LauncherPaging();private boolean updatingPage,closing,dead;
 private boolean powerWatching;
 private final BroadcastReceiver powerEvents=new BroadcastReceiver(){public void onReceive(Context c,Intent i){updatePreviewPower();}};
 private void updatePreviewPower(){PowerManager p=getSystemService(PowerManager.class);boolean saving=p!=null&&p.isPowerSaveMode();if(renderer!=null)renderer.powerSaving(saving);if(input!=null&&config!=null)input.active(resumed&&config.optJSONObject("effects").optBoolean("gyro")&&!(saving&&AppSettings.batteryStatic(this)));}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 public void onCreate(Bundle state){super.onCreate(state);try{
  paging.gestureFallback(true);id=getIntent().getStringExtra("id");if(id==null)throw new IllegalStateException("缺少预览内容");VideoApp app=(VideoApp)getApplication();app.job(id);config=new JSONObject();JSONObject effects=EffectOptions.normalize(new JSONObject(getIntent().getStringExtra("effects")));boolean pan=effects.optBoolean("pan")&&getIntent().getIntExtra("scope",0)!=1&&(!getIntent().getBooleanExtra("fit",false)||effects.optString("alignment").equals("free"));VideoApp.put(effects,"pan",pan);VideoApp.put(config,"effects",effects);VideoApp.put(config,"fit",getIntent().getBooleanExtra("fit",false));VideoApp.put(config,"pan",pan);
  FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.BLACK);texture=new TextureView(this);root.addView(texture,new FrameLayout.LayoutParams(-1,-1));
  LinearLayout controls=new LinearLayout(this);controls.setOrientation(1);controls.setPadding(dp(18),dp(10),dp(18),dp(20));controls.setBackgroundColor(0xb3101824);status=new TextView(this);status.setTextSize(12);status.setTextColor(Ui.MUTED);status.setVisibility(View.GONE);controls.addView(status);
  pageControls=new LinearLayout(this);pageControls.setOrientation(0);pageControls.setGravity(Gravity.CENTER_VERTICAL);pageControls.setVisibility(View.GONE);pageLabel=new TextView(this);pageLabel.setTextSize(12);pageLabel.setPadding(0,0,dp(8),0);pageLabel.setTextColor(Ui.ACCENT);pageControls.addView(pageLabel,new LinearLayout.LayoutParams(-2,-2));pages=effects.optString("pageMode").equals("manual")?effects.optInt("fallbackPages",3):3;pages=Math.max(1,pages);paging.pages(pages);paging.manual(true);page=new SeekBar(this);page.setMax(Math.max(1,pages-1)*1000);page.setProgress(page.getMax()/2);pageLabel.setText(pageText());page.setContentDescription("模拟桌面翻页，不是播放进度");page.setProgressTintList(android.content.res.ColorStateList.valueOf(Ui.ACCENT));page.setThumbTintList(android.content.res.ColorStateList.valueOf(Ui.ACCENT));page.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int p,boolean user){scroll=p/(float)b.getMax();if(!updatingPage)paging.position(scroll);pageLabel.setText(pageText());if(renderer!=null&&!updatingPage)renderer.offset(scroll);}});pageControls.addView(page,new LinearLayout.LayoutParams(0,dp(40),1));controls.addView(pageControls);
  LinearLayout actions=new LinearLayout(this);
  Button full=new Button(this);full.setText("全屏预览");full.setAllCaps(false);full.setTextColor(Ui.TEXT);full.setBackground(AppSheet.background(Ui.PANEL,dp(14)));full.setTag("preview-fullscreen");full.setOnClickListener(v->fullscreen(true));
  Button close=new Button(this);close.setText("返回设置");close.setAllCaps(false);close.setTextColor(0xff15362c);close.setBackground(AppSheet.background(Ui.ACCENT,dp(14)));close.setOnClickListener(v->finish());
  LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(0,dp(40),1),bp=new LinearLayout.LayoutParams(0,dp(40),1);bp.leftMargin=dp(8);actions.addView(full,fp);actions.addView(close,bp);
  LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,-2);ap.topMargin=dp(6);controls.addView(actions,ap);this.controls=controls;root.addView(controls,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));
  hint=new TextView(this);hint.setText("按返回键退出全屏");hint.setTextSize(12);hint.setTextColor(0xffffffff);hint.setPadding(dp(12),dp(6),dp(12),dp(6));hint.setBackground(AppSheet.background(0x99000000,dp(12)));hint.setVisibility(View.GONE);
  FrameLayout.LayoutParams hp=new FrameLayout.LayoutParams(-2,-2,Gravity.TOP|Gravity.CENTER_HORIZONTAL);hp.topMargin=dp(40);root.addView(hint,hp);
  root.setOnApplyWindowInsetsListener((v,i)->{controls.setPadding(dp(18)+i.getSystemWindowInsetLeft(),dp(10),dp(18)+i.getSystemWindowInsetRight(),dp(10)+i.getSystemWindowInsetBottom());return i;});setContentView(root);
  input=new MotionInput(this,(x,y)->{if(renderer!=null)renderer.tilt(x,y);},message->runOnUiThread(()->showStatus(message)));texture.setOnTouchListener((v,e)->{float x=e.getX()/Math.max(1,texture.getWidth()),y=e.getY()/Math.max(1,texture.getHeight());int action=e.getActionMasked();if(config.optBoolean("pan")&&paging.touch(x,y,action,SystemClock.elapsedRealtime())){scroll=paging.value();if(renderer!=null)renderer.offset(scroll,action==MotionEvent.ACTION_MOVE);updatingPage=true;page.setProgress(Math.round(scroll*page.getMax()));updatingPage=false;}if(renderer!=null)renderer.touch(x,y,action);return true;});
  texture.setSurfaceTextureListener(new TextureView.SurfaceTextureListener(){public void onSurfaceTextureAvailable(SurfaceTexture t,int w,int h){surface=new Surface(t);start();}public void onSurfaceTextureSizeChanged(SurfaceTexture t,int w,int h){if(renderer!=null)renderer.resize(w,h);}public boolean onSurfaceTextureDestroyed(SurfaceTexture t){stop();if(surface!=null){surface.release();surface=null;}return true;}public void onSurfaceTextureUpdated(SurfaceTexture t){}});
 }catch(Exception e){finish();}}
 private void start(){if(!resumed||dead||closing||surface==null)return;if(renderer!=null){if(renderer.hasFailed())stop();else renderer.visible(true);return;}VideoApp app=(VideoApp)getApplication();renderer=new WallpaperRenderer(this,new WallpaperRenderer.Events(){public void contentSize(int w,int h){runOnUiThread(()->{JSONObject o=config.optJSONObject("effects");android.util.DisplayMetrics d=getResources().getDisplayMetrics();pages=dev.workshopvideo.core.DesktopPages.resolve(o.optString("pageMode").equals("manual"),o.optInt("fallbackPages",3),WallpaperStore.prefs(WallpaperPreviewActivity.this).getInt("launcherPages",0),w,h,d.widthPixels,d.heightPixels,(float)o.optDouble("zoom",1));paging.pages(pages);paging.manual(true);if(pages<=1){scroll=.5f;paging.position(.5f);if(renderer!=null)renderer.offset(.5f,true);pageControls.setVisibility(View.GONE);}updatingPage=true;page.setMax(Math.max(1,pages-1)*1000);page.setProgress(Math.round(scroll*page.getMax()));updatingPage=false;pageLabel.setText(pageText());});}public void rendered(){}public void pagingAvailable(boolean available){runOnUiThread(()->pageControls.setVisibility(available&&pages>1?View.VISIBLE:View.GONE));}public void failed(String message){runOnUiThread(()->showStatus(message));}});renderer.surfaceFile(surface,texture.getWidth(),texture.getHeight(),app.video(id),config,true);renderer.offset(scroll);updatePreviewPower();}
 private LinearLayout controls;private TextView hint;private boolean fullscreen;
 private String pageText(){return "第 "+(Math.round(scroll*(pages-1))+1)+" / "+pages+" 页";}
 /** Only real messages (sensor or rendering problems) take space under the picture. */
 private void showStatus(String message){status.setText(message);status.setVisibility(message==null||message.isEmpty()?View.GONE:View.VISIBLE);}
 /** Full-screen preview: the picture alone, without controls or system bars, as on the home screen. Back returns. */
 private void fullscreen(boolean on){
  fullscreen=on;controls.setVisibility(on?View.GONE:View.VISIBLE);WindowInsetsController bars=getWindow().getInsetsController();
  if(bars!=null){if(on){bars.setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);bars.hide(WindowInsets.Type.systemBars());}else bars.show(WindowInsets.Type.systemBars());}
  hint.setVisibility(on?View.VISIBLE:View.GONE);if(on)hint.postDelayed(()->hint.setVisibility(View.GONE),2000);
 }
 @Override public void onBackPressed(){if(fullscreen){fullscreen(false);return;}super.onBackPressed();}
 private void stop(){if(input!=null)input.active(false);if(renderer!=null){WallpaperRenderer previous=renderer;renderer=null;closing=true;previous.closeAsync(()->runOnUiThread(()->{closing=false;start();}));}}
 protected void onResume(){super.onResume();resumed=true;if(!powerWatching){IntentFilter f=new IntentFilter(PowerManager.ACTION_POWER_SAVE_MODE_CHANGED);if(Build.VERSION.SDK_INT>=33)registerReceiver(powerEvents,f,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(powerEvents,f);powerWatching=true;}start();updatePreviewPower();}protected void onPause(){resumed=false;if(powerWatching){unregisterReceiver(powerEvents);powerWatching=false;}if(input!=null)input.active(false);if(renderer!=null)renderer.visible(false);super.onPause();}protected void onDestroy(){dead=true;stop();if(surface!=null)surface.release();super.onDestroy();}
}
